"""Distinct C++ contracts for the remediated skip-list task family."""

from __future__ import annotations

from dataclasses import dataclass, replace


@dataclass(frozen=True)
class Case:
    legacy_id: str
    task_id: str
    class_name: str
    mechanism: str
    contract: str
    header: str
    reference: str
    starter: str
    visible: str
    hidden: str
    required_tokens: tuple[str, ...]
    negative_name: str = ""
    negative_edits: tuple[tuple[str, str], ...] = ()


INCLUDES = """#include <cstddef>
#include <cstdint>
#include <optional>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <vector>
"""


def _header(body: str) -> str:
    return f"#pragma once\n{INCLUDES}\nnamespace curriculum {{\n{body}\n}}  // namespace curriculum\n"


def _source(body: str, mechanism: str) -> str:
    return f'''#include "task.h"
#include <algorithm>
#include <limits>
#include <stdexcept>
// mechanism:{mechanism}
namespace curriculum {{
{body}
}}  // namespace curriculum
'''


def _starter(body: str, mechanism: str) -> str:
    return _source(body, mechanism)


def _auction() -> Case:
    h = _header('''class AuctionPriceLevels {
 public:
  struct Fill { int order_id; int price; int quantity; };
  struct Level { int price; int quantity; std::size_t orders; };
  AuctionPriceLevels(); ~AuctionPriceLevels();
  AuctionPriceLevels(const AuctionPriceLevels&) = delete;
  bool add_order(int id,int price,int quantity);
  bool amend_quantity(int id,int quantity);
  bool cancel_order(int id);
  std::optional<Fill> consume_best(int quantity);
  std::vector<Level> levels(int low,int high) const;
  std::size_t order_count() const { return orders_.size(); }
  bool audit_for_test() const;
 private:
  struct Order { int id; int quantity; std::size_t sequence; Order* next; };
  struct Node { int price; int total; std::size_t count; std::vector<Node*> next; Order* first; Order* last; };
  Node* head_; std::unordered_map<int,std::pair<Node*,Order*>> orders_; std::size_t sequence_=0;
  static int height(int price); Node* find_level(int price) const;
  Node* ensure_level(int price); void remove_level(Node* node); void unlink_order(Node* level,Order* order);
};''')
    r = _source('''int AuctionPriceLevels::height(int price){unsigned x=static_cast<unsigned>(price)*2654435761U;int h=1;while(h<8&&(x&3U)==0U){++h;x>>=2U;}return h;}
AuctionPriceLevels::AuctionPriceLevels():head_(new Node{std::numeric_limits<int>::max(),0,0U,std::vector<Node*>(8,nullptr),nullptr,nullptr}){}
AuctionPriceLevels::~AuctionPriceLevels(){for(Node*n=head_->next[0];n;){Node*next=n->next[0];for(Order*o=n->first;o;){Order*x=o->next;delete o;o=x;}delete n;n=next;}delete head_;}
AuctionPriceLevels::Node* AuctionPriceLevels::find_level(int price)const{Node*n=head_;for(int l=7;l>=0;--l)while(n->next[static_cast<std::size_t>(l)]&&n->next[static_cast<std::size_t>(l)]->price>price)n=n->next[static_cast<std::size_t>(l)];n=n->next[0];return n&&n->price==price?n:nullptr;}
AuctionPriceLevels::Node* AuctionPriceLevels::ensure_level(int price){if(Node*n=find_level(price))return n;std::vector<Node*>update(8,head_);Node*n=head_;for(int l=7;l>=0;--l){while(n->next[static_cast<std::size_t>(l)]&&n->next[static_cast<std::size_t>(l)]->price>price)n=n->next[static_cast<std::size_t>(l)];update[static_cast<std::size_t>(l)]=n;}Node*made=new Node{price,0,0U,std::vector<Node*>(static_cast<std::size_t>(height(price)),nullptr),nullptr,nullptr};for(std::size_t l=0;l<made->next.size();++l){made->next[l]=update[l]->next[l];update[l]->next[l]=made;}return made;}
bool AuctionPriceLevels::add_order(int id,int price,int quantity){if(id<=0||price<=0||quantity<=0||orders_.count(id))return false;Node*level=ensure_level(price);Order*order=new Order{id,quantity,sequence_++,nullptr};if(level->last)level->last->next=order;else level->first=order;level->last=order;level->total+=quantity;++level->count;orders_[id]={level,order};return true;}
bool AuctionPriceLevels::amend_quantity(int id,int quantity){auto it=orders_.find(id);if(it==orders_.end()||quantity<=0)return false;Node*level=it->second.first;level->total+=quantity-it->second.second->quantity;it->second.second->quantity=quantity;return true;}
void AuctionPriceLevels::unlink_order(Node*level,Order*order){Order*prior=nullptr;for(Order*cur=level->first;cur&&cur!=order;cur=cur->next)prior=cur;if(prior)prior->next=order->next;else level->first=order->next;if(level->last==order)level->last=prior;level->total-=order->quantity;--level->count;orders_.erase(order->id);delete order;if(!level->count)remove_level(level);}
void AuctionPriceLevels::remove_level(Node*target){std::vector<Node*>update(8,head_);Node*n=head_;for(int l=7;l>=0;--l){while(n->next[static_cast<std::size_t>(l)]&&n->next[static_cast<std::size_t>(l)]!=target&&n->next[static_cast<std::size_t>(l)]->price>target->price)n=n->next[static_cast<std::size_t>(l)];update[static_cast<std::size_t>(l)]=n;}for(std::size_t l=0;l<target->next.size();++l)if(update[l]->next[l]==target)update[l]->next[l]=target->next[l];delete target;}
bool AuctionPriceLevels::cancel_order(int id){auto it=orders_.find(id);if(it==orders_.end())return false;unlink_order(it->second.first,it->second.second);return true;}
std::optional<AuctionPriceLevels::Fill> AuctionPriceLevels::consume_best(int quantity){if(quantity<=0||!head_->next[0])return std::nullopt;Node*level=head_->next[0];Order*order=level->first;const int filled=std::min(quantity,order->quantity);Fill out{order->id,level->price,filled};if(filled==order->quantity)unlink_order(level,order);else{order->quantity-=filled;level->total-=filled;}return out;}
std::vector<AuctionPriceLevels::Level> AuctionPriceLevels::levels(int low,int high)const{std::vector<Level>out;if(low>high||low<=0)return out;for(Node*n=head_->next[0];n;n=n->next[0])if(n->price>=low&&n->price<=high)out.push_back({n->price,n->total,n->count});return out;}
bool AuctionPriceLevels::audit_for_test()const{std::unordered_set<const Node*>base;int prior=std::numeric_limits<int>::max();std::size_t count=0;for(Node*n=head_->next[0];n;n=n->next[0]){if(n->price>=prior||n->next.empty())return false;prior=n->price;base.insert(n);int total=0;std::size_t members=0;for(Order*o=n->first;o;o=o->next){auto it=orders_.find(o->id);if(it==orders_.end()||it->second.first!=n||it->second.second!=o)return false;total+=o->quantity;++members;++count;}if(total!=n->total||members!=n->count||(n->last&&n->last->next))return false;}for(std::size_t l=1;l<8;++l){prior=std::numeric_limits<int>::max();for(Node*n=head_->next[l];n;n=n->next[l]){if(!base.count(n)||n->next.size()<=l||n->price>=prior)return false;prior=n->price;}}return count==orders_.size();}''', "descending-price-fifo-towers")
    s = _starter('''AuctionPriceLevels::AuctionPriceLevels():head_(nullptr){} AuctionPriceLevels::~AuctionPriceLevels()=default;int AuctionPriceLevels::height(int){return 1;}AuctionPriceLevels::Node*AuctionPriceLevels::find_level(int)const{return nullptr;}AuctionPriceLevels::Node*AuctionPriceLevels::ensure_level(int){return nullptr;}void AuctionPriceLevels::remove_level(Node*){}void AuctionPriceLevels::unlink_order(Node*,Order*){}bool AuctionPriceLevels::add_order(int,int,int){return false;}bool AuctionPriceLevels::amend_quantity(int,int){return false;}bool AuctionPriceLevels::cancel_order(int){return false;}std::optional<AuctionPriceLevels::Fill>AuctionPriceLevels::consume_best(int){return std::nullopt;}std::vector<AuctionPriceLevels::Level>AuctionPriceLevels::levels(int,int)const{return {};}bool AuctionPriceLevels::audit_for_test()const{return false;}''', "descending-price-fifo-towers")
    v = '''AuctionPriceLevels book; REQUIRE(book.add_order(1,100,4)); REQUIRE(book.add_order(2,110,3)); REQUIRE(book.add_order(3,110,2)); REQUIRE_FALSE(book.add_order(1,120,1)); REQUIRE(book.amend_quantity(1,5)); auto first=book.consume_best(2); REQUIRE(first); REQUIRE(first->order_id==2); REQUIRE(first->price==110); REQUIRE(first->quantity==2); auto levels=book.levels(90,120); REQUIRE(levels.size()==2U); REQUIRE(levels[0].price==110); REQUIRE(levels[0].quantity==3); REQUIRE(book.audit_for_test());'''
    x = '''AuctionPriceLevels book; for(int i=1;i<=80;++i)REQUIRE(book.add_order(i,90+i%9,1+i%5)); for(int i=4;i<=80;i+=4)REQUIRE(book.cancel_order(i)); for(int i=3;i<=80;i+=7)if(i%4)REQUIRE(book.amend_quantity(i,9)); int prior=1000;while(auto fill=book.consume_best(100)){REQUIRE(fill->price<=prior);prior=fill->price;REQUIRE(book.audit_for_test());}REQUIRE(book.order_count()==0U);'''
    return Case("skip-auction-price-levels","skip-auction-price-levels","AuctionPriceLevels","descending-price-fifo-towers","Descending price nodes own FIFO order buckets and aggregate quantity.",h,r,s,v,x,("struct Node","std::vector<Node*> next","Order* first","consume_best","audit_for_test"))


def _gap_calendar() -> Case:
    h = _header('''class GapCalendar { public: struct Reservation{int id;int start;int end;}; GapCalendar();~GapCalendar();GapCalendar(const GapCalendar&)=delete;bool reserve(int id,int start,int end);bool cancel(int id);std::optional<Reservation> reservation(int id)const;std::optional<int> first_gap(int after,int duration,int horizon)const;std::vector<Reservation> schedule()const;bool audit_for_test()const;private:struct Node{Reservation value;std::vector<Node*>next;};Node*head_;std::unordered_map<int,Node*>ids_;static int height(int id);void unlink(Node*);};''')
    r = _source('''int GapCalendar::height(int id){unsigned x=static_cast<unsigned>(id)*2246822519U;int h=1;while(h<7&&(x&1U)){++h;x>>=1U;}return h;}GapCalendar::GapCalendar():head_(new Node{{0,0,0},std::vector<Node*>(7,nullptr)}){}GapCalendar::~GapCalendar(){for(Node*n=head_->next[0];n;){Node*x=n->next[0];delete n;n=x;}delete head_;}bool GapCalendar::reserve(int id,int start,int end){if(id<=0||start<0||start>=end||ids_.count(id))return false;std::vector<Node*>u(7,head_);Node*n=head_;for(int l=6;l>=0;--l){while(n->next[static_cast<std::size_t>(l)]&&(n->next[static_cast<std::size_t>(l)]->value.start<start||(n->next[static_cast<std::size_t>(l)]->value.start==start&&n->next[static_cast<std::size_t>(l)]->value.id<id)))n=n->next[static_cast<std::size_t>(l)];u[static_cast<std::size_t>(l)]=n;}Node*next=u[0]->next[0];if(u[0]!=head_&&u[0]->value.end>start)return false;if(next&&end>next->value.start)return false;Node*made=new Node{{id,start,end},std::vector<Node*>(static_cast<std::size_t>(height(id)),nullptr)};for(std::size_t l=0;l<made->next.size();++l){made->next[l]=u[l]->next[l];u[l]->next[l]=made;}ids_[id]=made;return true;}void GapCalendar::unlink(Node*target){std::vector<Node*>u(7,head_);Node*n=head_;for(int l=6;l>=0;--l){while(n->next[static_cast<std::size_t>(l)]&&n->next[static_cast<std::size_t>(l)]!=target&&n->next[static_cast<std::size_t>(l)]->value.start<target->value.start)n=n->next[static_cast<std::size_t>(l)];u[static_cast<std::size_t>(l)]=n;}for(std::size_t l=0;l<target->next.size();++l)if(u[l]->next[l]==target)u[l]->next[l]=target->next[l];ids_.erase(target->value.id);delete target;}bool GapCalendar::cancel(int id){auto it=ids_.find(id);if(it==ids_.end())return false;unlink(it->second);return true;}std::optional<GapCalendar::Reservation>GapCalendar::reservation(int id)const{auto it=ids_.find(id);return it==ids_.end()?std::nullopt:std::optional<Reservation>(it->second->value);}std::optional<int>GapCalendar::first_gap(int after,int duration,int horizon)const{if(after<0||duration<=0||horizon<after||static_cast<long long>(after)+duration>horizon)return std::nullopt;int cursor=after;for(Node*n=head_->next[0];n;n=n->next[0]){if(n->value.end<=cursor)continue;if(static_cast<long long>(cursor)+duration<=n->value.start)return cursor;cursor=std::max(cursor,n->value.end);if(static_cast<long long>(cursor)+duration>horizon)return std::nullopt;}return static_cast<long long>(cursor)+duration<=horizon?std::optional<int>(cursor):std::nullopt;}std::vector<GapCalendar::Reservation>GapCalendar::schedule()const{std::vector<Reservation>out;for(Node*n=head_->next[0];n;n=n->next[0])out.push_back(n->value);return out;}bool GapCalendar::audit_for_test()const{int end=-1;std::unordered_set<const Node*>base;for(Node*n=head_->next[0];n;n=n->next[0]){if(n->value.start<end||n->next.empty()||ids_.find(n->value.id)==ids_.end())return false;end=n->value.end;base.insert(n);}for(std::size_t l=1;l<7;++l)for(Node*n=head_->next[l];n;n=n->next[l])if(!base.count(n)||n->next.size()<=l)return false;return base.size()==ids_.size();}''',"first-fit-gap-skip-index")
    s = _starter('''GapCalendar::GapCalendar():head_(nullptr){}GapCalendar::~GapCalendar()=default;int GapCalendar::height(int){return 1;}bool GapCalendar::reserve(int,int,int){return false;}void GapCalendar::unlink(Node*){}bool GapCalendar::cancel(int){return false;}std::optional<GapCalendar::Reservation>GapCalendar::reservation(int)const{return std::nullopt;}std::optional<int>GapCalendar::first_gap(int,int,int)const{return std::nullopt;}std::vector<GapCalendar::Reservation>GapCalendar::schedule()const{return {};}bool GapCalendar::audit_for_test()const{return false;}''',"first-fit-gap-skip-index")
    v='''GapCalendar c;REQUIRE(c.reserve(1,10,20));REQUIRE(c.reserve(2,25,30));REQUIRE_FALSE(c.reserve(3,19,26));REQUIRE(c.first_gap(0,10,40)==0);REQUIRE(c.first_gap(15,5,40)==20);REQUIRE(c.cancel(1));REQUIRE(c.first_gap(10,12,40)==10);REQUIRE(c.audit_for_test());'''
    x='''GapCalendar c;for(int i=0;i<50;++i)REQUIRE(c.reserve(i+1,i*4,i*4+2));for(int i=1;i<=50;i+=3)REQUIRE(c.cancel(i));auto all=c.schedule();for(std::size_t i=1;i<all.size();++i)REQUIRE(all[i-1].end<=all[i].start);for(int p=0;p<200;++p){auto gap=c.first_gap(p,1,205);REQUIRE(gap);REQUIRE(*gap>=p);}REQUIRE(c.audit_for_test());'''
    return Case("skip-calendar-slots","skip-gap-calendar","GapCalendar","first-fit-gap-skip-index","A non-overlapping interval tower answers earliest first-fit gaps.",h,r,s,v,x,("struct Node","std::vector<Node*>next","first_gap","value.end>start","audit_for_test"))


def _tower_merge() -> Case:
    h=_header('''class TowerMergeManifest{public:struct Item{int id;int key;int height;};TowerMergeManifest();~TowerMergeManifest();TowerMergeManifest(const TowerMergeManifest&)=delete;bool add_left(Item);bool add_right(Item);bool merge_right();std::vector<Item>left_items()const;std::vector<Item>right_items()const;bool audit_for_test()const;private:struct Node{Item value;std::vector<Node*>next;};Node*left_;Node*right_;std::unordered_set<int>ids_;static bool before(const Item&,const Item&);bool insert(Node*,Item);static std::vector<Item>values(Node*);static bool audit(Node*);};''')
    r=_source('''bool TowerMergeManifest::before(const Item&a,const Item&b){return a.key!=b.key?a.key<b.key:a.id<b.id;}TowerMergeManifest::TowerMergeManifest():left_(new Node{{0,0,8},std::vector<Node*>(8,nullptr)}),right_(new Node{{0,0,8},std::vector<Node*>(8,nullptr)}){}TowerMergeManifest::~TowerMergeManifest(){for(Node*head:{left_,right_}){for(Node*n=head->next[0];n;){Node*x=n->next[0];delete n;n=x;}delete head;}}bool TowerMergeManifest::insert(Node*head,Item item){if(item.id<=0||item.key<0||item.height<1||item.height>8||ids_.count(item.id))return false;std::vector<Node*>u(8,head);Node*n=head;for(int l=7;l>=0;--l){while(n->next[static_cast<std::size_t>(l)]&&before(n->next[static_cast<std::size_t>(l)]->value,item))n=n->next[static_cast<std::size_t>(l)];u[static_cast<std::size_t>(l)]=n;}Node*made=new Node{item,std::vector<Node*>(static_cast<std::size_t>(item.height),nullptr)};for(int l=0;l<item.height;++l){made->next[static_cast<std::size_t>(l)]=u[static_cast<std::size_t>(l)]->next[static_cast<std::size_t>(l)];u[static_cast<std::size_t>(l)]->next[static_cast<std::size_t>(l)]=made;}ids_.insert(item.id);return true;}bool TowerMergeManifest::add_left(Item x){return insert(left_,x);}bool TowerMergeManifest::add_right(Item x){return insert(right_,x);}bool TowerMergeManifest::merge_right(){if(!right_->next[0])return false;Node*a=left_->next[0];Node*b=right_->next[0];Node*tail=left_;while(a||b){Node*take;if(!b||(a&&before(a->value,b->value))){take=a;a=a->next[0];}else{take=b;b=b->next[0];}tail->next[0]=take;tail=take;}tail->next[0]=nullptr;for(std::size_t l=1;l<8;++l){Node*level_tail=left_;for(Node*n=left_->next[0];n;n=n->next[0])if(n->value.height>static_cast<int>(l)){level_tail->next[l]=n;level_tail=n;}level_tail->next[l]=nullptr;}for(std::size_t l=0;l<8;++l)right_->next[l]=nullptr;return true;}std::vector<TowerMergeManifest::Item>TowerMergeManifest::values(Node*h){std::vector<Item>out;for(Node*n=h->next[0];n;n=n->next[0])out.push_back(n->value);return out;}std::vector<TowerMergeManifest::Item>TowerMergeManifest::left_items()const{return values(left_);}std::vector<TowerMergeManifest::Item>TowerMergeManifest::right_items()const{return values(right_);}bool TowerMergeManifest::audit(Node*h){std::unordered_set<Node*>base;Node*p=nullptr;for(Node*n=h->next[0];n;n=n->next[0]){if(p&&!before(p->value,n->value))return false;base.insert(n);p=n;}for(std::size_t l=1;l<8;++l){p=nullptr;for(Node*n=h->next[l];n;n=n->next[l]){if(!base.count(n)||n->value.height<=static_cast<int>(l)||(p&&!before(p->value,n->value)))return false;p=n;}}return true;}bool TowerMergeManifest::audit_for_test()const{return audit(left_)&&audit(right_);}''',"pointer-splice-tower-merge")
    s=_starter('''TowerMergeManifest::TowerMergeManifest():left_(nullptr),right_(nullptr){}TowerMergeManifest::~TowerMergeManifest()=default;bool TowerMergeManifest::before(const Item&,const Item&){return false;}bool TowerMergeManifest::insert(Node*,Item){return false;}bool TowerMergeManifest::add_left(Item){return false;}bool TowerMergeManifest::add_right(Item){return false;}bool TowerMergeManifest::merge_right(){return false;}std::vector<TowerMergeManifest::Item>TowerMergeManifest::values(Node*){return {};}std::vector<TowerMergeManifest::Item>TowerMergeManifest::left_items()const{return {};}std::vector<TowerMergeManifest::Item>TowerMergeManifest::right_items()const{return {};}bool TowerMergeManifest::audit(Node*){return false;}bool TowerMergeManifest::audit_for_test()const{return false;}''',"pointer-splice-tower-merge")
    v='''TowerMergeManifest m;REQUIRE(m.add_left({1,10,1}));REQUIRE(m.add_left({3,30,3}));REQUIRE(m.add_right({2,20,2}));REQUIRE(m.add_right({4,30,4}));REQUIRE_FALSE(m.add_right({1,9,2}));REQUIRE(m.merge_right());REQUIRE(m.right_items().empty());auto v=m.left_items();REQUIRE(v.size()==4U);REQUIRE(v[2].id==3);REQUIRE(v[3].id==4);REQUIRE(m.audit_for_test());'''
    x='''TowerMergeManifest m;for(int i=1;i<=120;++i){TowerMergeManifest::Item x{i,(i*37)%101,1+i%8};REQUIRE((i%2?m.add_left(x):m.add_right(x)));}REQUIRE(m.merge_right());REQUIRE_FALSE(m.merge_right());auto v=m.left_items();for(std::size_t i=1;i<v.size();++i)REQUIRE((v[i-1].key<v[i].key||(v[i-1].key==v[i].key&&v[i-1].id<v[i].id)));REQUIRE(m.audit_for_test());'''
    return Case("skip-cargo-priorities","skip-tower-merge-manifest","TowerMergeManifest","pointer-splice-tower-merge","Two explicit-height towers merge by node splice and higher-level rebuild.",h,r,s,v,x,("Node*left_","Node*right_","merge_right","level_tail","audit_for_test"))


