def _bind_negatives(cases: tuple[Case, ...]) -> tuple[Case, ...]:
    if set(_NEGATIVES) != {case.task_id for case in cases}:
        raise RuntimeError("negative fixture inventory does not match skip-list cases")
    bound = []
    for case in cases:
        name, edits = _NEGATIVES[case.task_id]
        bound.append(replace(case, negative_name=name, negative_edits=edits))
    return tuple(bound)


CASES = _bind_negatives(first_cases() + second_cases() + third_cases() + fourth_cases())
